UNION
SELECT f.id, f.parent_id, f.name FROM folder_info f RIGHT JOIN folder_cte cte ON f.parent_id = cte.id WHERE type = #{type} AND status = 1
AND f.parent_id not in
#{cid}
) SELECT DISTINCT id, parent_id, name FROM folder_cte t1
AND t1.id not in
